query:
UPDATE course_lessons SET content = REPLACE(
  REPLACE(content,
    'OSSD1 and OSSD2: Must be wired to a safety relay or safety PLC. Never wire them directly to a standard standard relay or contactor.',
    'OSSD1 and OSSD2: Must be wired to a safety-rated device. Typically this is a safety relay or safety PLC. They can also be wired directly to safety contactors with force-guided contacts in a redundant configuration with feedback monitoring (Category 3/4 architectures). Never wire them to a standard (non-safety-rated) relay or contactor without redundancy and monitoring.'
  ),
  'K: Approach speed of the body part (typically 1600 mm/s for hand/arm)',
  'K: Approach speed of the body part. Per ISO 13855: use K = 2000 mm/s when the calculated distance is ≤ 500mm (perpendicular approach), or K = 1600 mm/s when the distance is > 500mm (parallel approach or walking speed)'
) WHERE id = 120023;

